import json
from pathlib import Path
p=Path(__file__).parent
orig=json.loads((p/'Catalog/temporary_loads.json').read_text(encoding='utf-8'))['records']
idmap={x['id']:x for x in orig}
# Categories have user-facing context. Duplicate corridor rows are deliberate shortcuts.
groups=[
 ('Жилые помещения',[('T-00012','Квартиры, гостиницы, общежития, спальни, палаты, террасы'),('T-00029','Коридоры, лестницы и вестибюли жилых зданий'),('T-00026','Балконы: полоса 0,8 м вдоль ограждения'),('T-00027','Балконы: вся площадь'),('T-00024','Крыши и покрытия для отдыха')]),
 ('Офисы и учёба',[('T-00013','Офисы, кабинеты, классы и бытовые помещения'),('T-00014','Лаборатории, кабинеты врачей, кухни, техэтажи до 75 м'),('T-00029','Коридоры, лестницы и вестибюли при офисах, классах и лабораториях'),('T-00015','Читальные залы'),('T-00030','Коридоры и лестницы при читальных залах')]),
 ('Кафе, торговля и мероприятия',[('T-00016','Обеденные залы кафе, ресторанов и столовых'),('T-00017','Залы собраний, концертов, танцев, спорта и фитнеса'),('T-00018','Торговые и выставочные залы'),('T-00019','Сцены театров и концертных залов'),('T-00030','Коридоры, лестницы и фойе при залах и сценах')]),
 ('Трибуны и вокзалы',[('T-00020','Трибуны с закреплёнными сиденьями'),('T-00021','Трибуны для стоящих зрителей'),('T-00031','Коридоры, лестницы и проходы при трибунах'),('T-00032','Перроны вокзалов, платформы и пассажирские переходы'),('T-00030','Вестибюли и лестницы вокзалов')]),
 ('Производственные и складские',[('T-00002','Производственный склад: плиты и второстепенные балки'),('T-00003','Производственный склад: ригели, колонны, фундаменты'),('T-00001','Торговые склады'),('T-00004','Архивы и книгохранилища'),('T-00028','Площадки обслуживания и ремонта оборудования'),('T-00030','Коридоры и лестницы производственных площадок обслуживания')]),
 ('Крыши, чердаки, балконы',[('T-00022','Чердаки'),('T-00023','Покрытия с возможным скоплением людей'),('T-00024','Покрытия, используемые для отдыха'),('T-00025','Прочие покрытия'),('T-00026','Балконы: полоса шириной 0,8 м вдоль ограждения'),('T-00027','Балконы: вся площадь')]),
 ('Автостоянки',[('T-00042','Автостоянка до 3 т: место парковки'),('T-00043','Автостоянка до 3 т: пандус и проезд'),('T-00044','Автостоянка 3–16 т: место парковки'),('T-00045','Автостоянка 3–16 т: пандус и проезд')]),
 ('Поручни и местные нагрузки',[('T-00035','Поручни жилых, детских и медицинских учреждений'),('T-00036','Поручни трибун и спортивных залов'),('T-00037','Поручни остальных зданий'),('T-00038','Поручни обслуживающих площадок и мостиков'),('T-00039','Сосредоточенная нагрузка: перекрытия и лестницы'),('T-00040','Сосредоточенная нагрузка: чердаки, покрытия, террасы, балконы'),('T-00041','Сосредоточенная нагрузка: покрытия с проходом только по трапам')]),
 ('Сельскохозяйственные',[('T-00033','Помещения для мелкого скота'),('T-00034','Помещения для крупного скота')]),
]
# Some rows are minimum values requiring specification by designer. Keep explicit in metadata.
needs_task={'T-00002','T-00003','T-00001','T-00004','T-00014','T-00018','T-00019','T-00028','T-00033','T-00034','T-00044','T-00045'}
notes={
'T-00022':'Учитывается на площади, не занятой оборудованием и материалами.',
'T-00023':'Не учитывается одновременно со снеговой нагрузкой.',
'T-00024':'Не учитывается одновременно со снеговой нагрузкой.',
'T-00025':'Не учитывается одновременно со снеговой нагрузкой.',
'T-00026':'Для проверки балкона и места его защемления; для нижележащих конструкций действуют правила примечания 3 таблицы 8.3.',
'T-00027':'Сравнить с полосовой нагрузкой на балкон; следует учитывать наиболее неблагоприятный случай.',
'T-00017':'Для танцевальных и спортивных залов дополнительно учитывать динамические воздействия согласно примечанию 5 к таблице 8.3.',
'T-00019':'Для сцены учитывать динамические воздействия согласно примечанию 5 к таблице 8.3.',
'T-00020':'Для трибун спортивных сооружений учитывать динамические воздействия согласно примечанию 5 к таблице 8.3.',
'T-00021':'Для трибун спортивных сооружений учитывать динамические воздействия согласно примечанию 5 к таблице 8.3.',
'T-00042':'Равномерная и сосредоточенная нагрузки используются для разных проверок, не складываются.',
'T-00043':'Равномерная и сосредоточенная нагрузки используются для разных проверок, не складываются.',
'T-00044':'По заданию на проектирование, но не менее табличного значения.',
'T-00045':'По заданию на проектирование, но не менее табличного значения.',
}
rows=[]
for category,items in groups:
 for i,(srcid,title) in enumerate(items):
  x=idmap[srcid];pa=x['params'];q=pa.get('q_kPa');P=pa.get('P_kN');line=pa.get('line_load_kN_per_m')
  if q is not None:typ='Равномерная';unit='кПа';n=q
  elif line is not None:typ='Погонная';unit='кН/м';n=line
  else:typ='Сосредоточенная';unit='кН';n=P
  gamma=pa.get('gamma_f')
  if gamma is None and q is not None:gamma=1.3 if q<2 else 1.2
  # Table 8.1 industrial/warehouse: gamma depends on material, not automatically 1.2 for all.
  if srcid in ('T-00001','T-00002','T-00003','T-00004'):gamma=1.2 # For warehousing materials and archives per table 8.2; clarify basis in notes.
  rows.append(dict(id=srcid+'-'+str(len(rows)+1),source_id=srcid,category=category,title=title,type=typ,unit=unit,norm=n,gamma=gamma,design=round(n*gamma,4) if n is not None and gamma else None,extra_point_kN=P if q is not None else None,source=x['source'],notes=notes.get(srcid,''),minimum=srcid in needs_task))
# Explicit temporary partitions not yet included; gamma depends on source material per §7.2 and cannot safely be auto selected.
result={'version':1,'categories':[g[0] for g in groups],'records':rows}
(p/'Catalog/sp20_guide.json').write_text(json.dumps(result,ensure_ascii=False,indent=2),encoding='utf-8')
print('SP20 curated:',len(rows))
